int font_glyph_index(const font_t *font, char c)
{
    const uint8_t *map;
    if (font == &FONT_BIG) {
        map = FONT_BIG_MAP;
    } else if (font == &FONT_MED) {
        map = FONT_MED_MAP;
    } else if (font == &FONT_SMALL) {
        map = FONT_SMALL_MAP;
    } else {
        return -1;
    }

    uint8_t code = (uint8_t)c;
    if (code >= 128U) {
        return -1;
    }
    uint8_t idx = map[code];
    return idx == 0xFFU ? -1 : (int)idx;
}
